                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    new_mod = (mod * 10 + d) % k
                total += dp(pos + 1, new_tight, new_started, new_diff, new_mod)
            return total

        return dp(0, True, False, 0, 0)

    return f(high) - f(low - 1)

