def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_cells = h * w
    grid = [[False] * w for _ in range(h)]
    used = 0

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return (r, c)
        return None

    def can_place(tr, tc, th, tw):
        for dr in range(th):
            for dc in range(tw):
                if tr + dr >= h or tc + dc >= w or grid[tr + dr][tc + dc]:
                    return False
        return True

    def place(tr, tc, th, tw, val=True):
        for dr in range(th):
            for dc in range(tw):
                grid[tr + dr][tc + dc] = val

    def backtrack():
        empty = first_empty()
        if empty is None:
            return True
        r, c = empty
        for i in range(n):
            if (used >> i) & 1:
                continue
            a, b = tiles[i]
            orientations = [(a, b)]
            if a != b:
                orientations.append((b, a))
            for th, tw in orientations:
                tr_min = max(0, r - th + 1)
                tr_max = min(r, h - th)
                tc_min = max(0, c - tw + 1)
                tc_max = min(c, w - tw)
                for tr in range(tr_min, tr_max + 1):
                    for tc in range(tc_min, tc_max + 1):
                        if can_place(tr, tc, th, tw):
                            place(tr, tc, th, tw, True)
                            used |= (1 << i)
                            if backtrack():
                                return True
                            used &= ~(1 << i)
                            place(tr, tc, th, tw, False)
        return False

    return backtrack()

