def min_absolute_difference(nums: List[int], k: int) -> int:
    min_diff = float('inf')
    prev_or = set()
    for num in nums:
        cur_or = {num}
        for val in prev_or:
            cur_or.add(val | num)
        for val in cur_or:
            diff = abs(k - val)
            if diff < min_diff:
                min_diff = diff
        prev_or = cur_or
    return min_diff

def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7
    if n == 1:
        return m % MOD
    r = n - k
    if r < 1 or r > n:
        return 0
    N = n - 1
    R = r - 1
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD
    comb = fact[N] * pow(fact[R], MOD-2, MOD) % MOD * pow(fact[N-R], MOD-2, MOD) % MOD
    if m == 1:
        ways_values = 1 if r == 1 else 0
    else:
        ways_values = m * pow(m-1, r-1, MOD) % MOD
    return (comb * ways_values) % MOD

