def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    max_d = int(round(n ** (1/3))) + 1
    for d in range(1, max_d + 1):
        if n % d != 0:
            continue
        m = n // d
        Delta = 12 * m - 3 * d * d
        if Delta < 0:
            continue
        s = math.isqrt(Delta)
        if s * s != Delta:
            continue
        num = s - 3 * d
        if num <= 0:
            continue
        if num % 6 != 0:
            continue
        y = num // 6
        x = y + d
        if x > 0 and y > 0 and x**3 - y**3 == n:
            return (x, y)
    return None

def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def decrement(s):
        if s == "1":
            return "0"
        digits = [int(c) for c in s]
        i = len(digits) - 1
        while i >= 0 and digits[i] == 0:
            digits[i] = 9
            i -= 1
        digits[i] -= 1
        res = ''.join(str(d) for d in digits).lstrip('0')
        return res if res else "0"

    def count_leq(X):
        if X == "0":
            return 0
        from functools import lru_cache
        n = len(X)

        @lru_cache(maxsize=None)
        def dp(idx, prev, tight, started):
            if idx == n:
                return 1 if started else 0
            limit = int(X[idx]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                if not started:
                    if d == 0:
                        total += dp(idx + 1, -1, new_tight, False)
                    else:
                        total += dp(idx + 1, d, new_tight, True)
                else:
                    if abs(d - prev) == 1:
                        total += dp(idx + 1, d, new_tight, True)
            return total % MOD

        return dp(0, -1, True, False) % MOD

    low_minus_1 = decrement(low)
    ans = (count_leq(high) - count_leq(low_minus_1)) % MOD
    return ans

