def min_spanning_tree_mod_k(n: int, m: int, k: int, edges: List[Tuple[int, int, int]]) -> int:
    if k == 1:
        return 0
    min_mod = k
    for combo in itertools.combinations(edges, n - 1):
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return False
            parent[rx] = ry
            return True
        total = 0
        ok = True
        for u, v, w in combo:
            if not union(u, v):
                ok = False
                break
            total += w
        if ok:
            root = find(1)
            connected = all(find(i) == root for i in range(2, n + 1))
            if connected:
                mod_val = total % k
                if mod_val < min_mod:
                    min_mod = mod_val
                    if min_mod == 0:
                        return 0
    return min_mod

