def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play a modified tic-tac-toe game on a 3x3 grid where each cell has a value."""

    def has_won(board, player):
        """Check if player has won on the board."""
        p = 1 if player == "Takahashi" else 2
        # Check rows
        for i in range(3):
            if all(board[i][j] == p for j in range(3)):
                return True
        # Check columns
        for j in range(3):
            if all(board[i][j] == p for i in range(3)):
                return True
        # Check diagonals
        if all(board[i][i] == p for i in range(3)):
            return True
        if all(board[i][2 - i] == p for i in range(3)):
            return True
        return False

    def is_full(board):
        """Check if board is full (no empty cells)."""
        return all(board[i][j] != 0 for i in range(3) for j in range(3))

    def get_score(board, player):
        """Get total score for a player."""
        p = 1 if player == "Takahashi" else 2
        return sum(grid[i][j] for i in range(3) for j in range(3) if board[i][j] == p)

    @lru_cache(maxsize=None)
    def minimax(board, player):
        """Minimax with memoization. Returns 1 if Takahashi wins, -1 if Aoki wins."""
        # Check terminal conditions
        if has_won(board, "Takahashi"):
            return 1
        if has_won(board, "Aoki"):
            return -1
        if is_full(board):
            takahashi_score = get_score(board, "Takahashi")
            aoki_score = get_score(board, "Aoki")
            if takahashi_score > aoki_score:
                return 1
            else:
                return -1

        # Available moves
        moves = [(i, j) for i in range(3) for j in range(3) if board[i][j] == 0]

        if player == 1:  # Takahashi's turn - maximize
            best = -float('inf')
            for i, j in moves:
                new_board = [list(row) for row in board]
                new_board[i][j] = 1
                result = minimax(tuple(tuple(row) for row in new_board), 2)
                best = max(best, result)
            return best
        else:  # Aoki's turn - minimize
            best = float('inf')
            for i, j in moves:
                new_board = [list(row) for row in board]
                new_board[i][j] = 2
                result = minimax(tuple(tuple(row) for row in new_board), 1)
                best = min(best, result)
            return best

    # Initial board: all 0 (empty), player 1 (Takahashi) to move
    initial_board = ((0, 0, 0), (0, 0, 0), (0, 0, 0))
    result = minimax(initial_board, 1)
    return "Takahashi" if result > 0 else "Aoki"

