def max_distinct_sum_three_parts(arr: List[int]) -> int:
    n = len(arr)
    if n < 3:
        return 0

    leftDistinct = [0] * (n + 1)
    seen = set()
    for i in range(n):
        seen.add(arr[i])
        leftDistinct[i+1] = len(seen)

    rightDistinct = [0] * (n + 2)
    seen = set()
    for i in range(n-1, -1, -1):
        seen.add(arr[i])
        rightDistinct[i] = len(seen)

    max_sum = 0

    for i in range(1, n-1):
        freq = {}
        distinct_mid = 0
        for j in range(i+1, n):
            val = arr[j-1]
            if freq.get(val, 0) == 0:
                distinct_mid += 1
            freq[val] = freq.get(val, 0) + 1

            current = leftDistinct[i] + distinct_mid + rightDistinct[j]
            if current > max_sum:
                max_sum = current

    return max_sum

def shortest_palindrome_with_prefix(s: str) -> str:
    n = len(s)
    if n == 0:
        return s
    rev = s[::-1]
    t = rev + '#' + s
    pi = [0] * len(t)
    for i in range(1, len(t)):
        j = pi[i-1]
        while j > 0 and t[i] != t[j]:
            j = pi[j-1]
        if t[i] == t[j]:
            j += 1
        pi[i] = j
    L = pi[-1]
    return s + s[:n-L][::-1]

