def count_power_representations(n: int) -> int:
    if n < 1:
        return 0

    def mobius(k: int) -> int:
        if k == 1:
            return 1
        factors = 0
        d = 2
        while d * d <= k:
            if k % d == 0:
                k //= d
                if k % d == 0:
                    return 0
                factors += 1
            d += 1 if d == 2 else 2
        if k > 1:
            factors += 1
        return -1 if factors % 2 else 1

    max_k = 0
    power = 1
    while True:
        power *= 2
        if power <= n:
            max_k += 1
        else:
            break

    total = 1  # count 1

    for k in range(2, max_k + 1):
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= n:
                lo = mid
            else:
                hi = mid - 1
        r = lo
        if r < 2:
            break
        mu = mobius(k)
        total += -mu * (r - 1)

    return total

