def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    def check_win(board, player):
        for r in range(3):
            if all(board[r][c] == player for c in range(3)):
                return True
        for c in range(3):
            if all(board[r][c] == player for r in range(3)):
                return True
        if all(board[i][i] == player for i in range(3)):
            return True
        if all(board[i][2-i] == player for i in range(3)):
            return True
        return False

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(board_tuple, turn):
        board = [list(row) for row in board_tuple]
        empties = [(r,c) for r in range(3) for c in range(3) if board[r][c] == 0]
        if not empties:
            tak_score = sum(grid[r][c] for r in range(3) for c in range(3) if board[r][c] == 1)
            aoki_score = sum(grid[r][c] for r in range(3) for c in range(3) if board[r][c] == -1)
            return "Takahashi" if tak_score > aoki_score else "Aoki"

        if turn == 0:  # Takahashi
            for r,c in empties:
                new_board = [row[:] for row in board]
                new_board[r][c] = 1
                if check_win(new_board, 1):
                    return "Takahashi"
                res = solve(tuple(map(tuple, new_board)), 1)
                if res == "Takahashi":
                    return "Takahashi"
            return "Aoki"
        else:  # Aoki
            for r,c in empties:
                new_board = [row[:] for row in board]
                new_board[r][c] = -1
                if check_win(new_board, -1):
                    return "Aoki"
                res = solve(tuple(map(tuple, new_board)), 0)
                if res == "Aoki":
                    return "Aoki"
            return "Takahashi"

    initial_board = ((0,0,0),(0,0,0),(0,0,0))
    return solve(initial_board, 0)

def max_eleven_twentytwo_subsequence(s: str, l: int, r: int) -> int:
    sub = s[l-1:r]
    max_k = 0
    for i, ch in enumerate(sub):
        if ch == '/':
            count1 = sub[:i].count('1')
            count2 = sub[i+1:].count('2')
            k = min(count1, count2)
            if k > max_k:
                max_k = k
    if '/' not in sub:
        return 0
    return 2 * max_k + 1

def min_grid_sum(H: int, W: int, grid: list[str]) -> int:
    n = 1 << W
    cnt = [0] * n
    for row in grid:
        m = int(row, 2)
        cnt[m] += 1
    f = [0] * n
    for x in range(n):
        pop = bin(x).count('1')
        f[x] = min(pop, W - pop)
    def fwht(a, invert=False):
        step = 1
        while step < n:
            for i in range(0, n, step * 2):
                for j in range(i, i + step):
                    u = a[j]
                    v = a[j + step]
                    a[j] = u + v
                    a[j + step] = u - v
            step <<= 1
        if invert:
            for i in range(n):
                a[i] //= n
    fwht(cnt, invert=False)
    fwht(f, invert=False)
    for i in range(n):
        cnt[i] *= f[i]
    fwht(cnt, invert=True)
    return min(cnt)

def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    def modpow(base, exp, mod):
        result = 1
        base %= mod
        while exp > 0:
            if exp & 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp >>= 1
        return result
    term1 = modpow(m - 1, n, MOD)
    if n % 2 == 0:
        term2 = (m - 1) % MOD
    else:
        term2 = (-(m - 1)) % MOD
    return (term1 + term2) % MOD

import math

def _count_distinct_prime_factors(n: int) -> int:
    """Count the number of distinct prime factors of n."""
    count = 0
    # Check factor 2
    if n % 2 == 0:
        count += 1
        while n % 2 == 0:
            n //= 2
    # Check odd factors
    d = 3
    while d * d <= n:
        if n % d == 0:
            count += 1
            while n % d == 0:
                n //= d
        d += 2
    if n > 1:
        count += 1
    return count

def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a."""
    x = math.isqrt(a)
    while x > 0:
        if _count_distinct_prime_factors(x) == 2:
            return x * x
        x -= 1
    return 36  # fallback; a >= 36 guarantees we always find at least 36

