def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    from functools import lru_cache
    full_mask = (1 << n) - 1

    @lru_cache(maxsize=None)
    def win(mask):
        bits = [i for i in range(n) if mask & (1 << i)]
        if len(bits) < 2:
            return False
        for i_idx in range(len(bits)):
            i = bits[i_idx]
            for j_idx in range(i_idx + 1, len(bits)):
                j = bits[j_idx]
                if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                    new_mask = mask ^ (1 << i) ^ (1 << j)
                    if not win(new_mask):
                        return True
        return False

    return "Takahashi" if win(full_mask) else "Aoki"

